def unit_of_work(function, metadata=None, timeout=None):
    """
    Decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")
    if timeout is not None and not isinstance(timeout, (float, int)):
        raise TypeError("timeout must be a float or int")
    if timeout is not None and timeout < 0:
        raise ValueError("timeout must be a positive value")

    def wrapper(*args, **kwargs):
        # Initialize the transaction
        transaction = DriverManager.instance().begin_transaction()
        try:
            # Invoke the transaction function with the transaction object
            result = function(transaction, *args, **kwargs)
            # Commit the transaction
            transaction.commit()
        except:
            # Rollback the transaction if an exception occurred
            transaction.rollback()
            raise
        else:
            # Return the result of the transaction
            return result

    return wrapper

