        ttl_value = ttl
        cache = {}
        prev_time = timer()
        next_ttl = prev_time + ttl_value
        next_last_access_time = prev_time

        def inner_wrapper(*args, **kwargs):
            nonlocal max_size, ttl_value, cache, prev_time, next_ttl, next_last_access_time
            cur_time = timer()
            cur_ttl = ttl_value
            cur_last_access_time = next_last_access_time
            key = repr(args) + repr(kwargs)
            ttl_value = cur_time + ttl_value
            next_ttl = ttl_value
            if key in cache:
                result, access_time = cache[key]
                if access_time >= cur_ttl:
