def deep_merge_nodes(nodes):
    """
    Deep merge node values in a list of tuples, where each tuple contains a ScalarNode as a key and a MappingNode as a value.
    If there are colliding keys with non-MappingNode values (e.g., integers or strings), the last of the values wins.
    """
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if isinstance(value, MappingNode):
            if key not in merged_nodes:
                merged_nodes[key] = MappingNode(tag=value.tag, value=[])
            for subkey, subvalue in value.value:
                merged_nodes[key].value.append((subkey, subvalue))
        else:
            merged_nodes[key] = value
    return [Node(key=key, value=value) for key, value in merged_nodes.items()]
