def _split_posix(s):
    import shlex
    return shlex.split(s)

def _split_windows(s):
    # https://stackoverflow.com/a/33514395
    result = []
    current = ''
    in_quote = False
    for c in s:
        if c == '"':
            if in_quote:
                in_quote = False
            else:
                in_quote = True
        elif c == ' ' and not in_quote:
            if current != '':
                result.append(current)
                current = ''
        else:
            current += c
    if current != '':
        result.append(current)
    return result
