def _verify(iface, candidate, tentative=False, vtype=None):
    # Check that the candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate does not provide the interface")

    # Check that the candidate defines all the necessary methods
    for name, method in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            raise Invalid("Candidate is missing method %s" % name)
        if not inspect.ismethod(getattr(candidate, name)):
            raise Invalid("Method %s is not a method" % name)
        if method.getSignatureString() != inspect.signature(getattr(candidate, name)):
            raise Invalid("Method %s has an incorrect signature" % name)

    # Check that the candidate defines all the necessary attributes
    for name, attr in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            raise Invalid("Candidate is missing attribute %s" % name)
        if not isinstance(getattr(candidate, name), attr.type):
