def verifyObject(iface,
                 candidate,
                 tentative=False):
    # Check if the candidate claims to provide the interface
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(
                f"{candidate} does not provide {iface}")

    # Check that the candidate has the necessary methods
    for method_name in iface.getMethodNames():
        if not hasattr(candidate, method_name):
            raise zope.interface.Invalid(
                f"{candidate} does not have a method {method_name}"
            )

    # Check that the methods have the correct signature
    for method_name in iface.getMethodNames():
        if not inspect.signature(getattr(candidate, method_name)).equals(iface.methods[method_name]):
            raise zope.interface.Invalid(
                f"{candidate}.{method_name} does not have the correct signature"
            )

    # Check that the candidate has the necessary attributes
    for attr_name in iface.getAttributeNames():
        if not hasattr(candidate, attr_name):
            raise zope.interface.Invalid(
                f"{candidate} does not have an attribute {attr_name}"
