def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from OpenSSL.crypto import sign, verify, load_pkcs12
    except ImportError:
        raise ImportError("Python OpenSSL library is not installed.")
    try:
        xml_doc = ET.fromstring(doc)
    except ET.ParseError:
        raise ValueError("Invalid XML document.")
    signed_data = xml_doc.get("SignedSignatureData", None)
    if not signed_data:
        raise ValueError("Signed signature is missing.")
    signed_info = signed_data.get("SignedInfo", None)
    if not signed_info:
        raise ValueError("Signed info is missing.")
    signature_value = signed_info.find("SignatureValue", ns="http://www.w3.org/2000/09/xmldsig#")
    if not signature_value:
        raise ValueError("Signature value is missing.")
    certificate = signed_info.find("X509Certificate", ns="http://www.w3.org/2000/09/xmldsig#")
    if not certificate:
        raise ValueError("Certificate is missing.")
    # Verify the signature against the certificate
    cert_obj = load_pkcs12(certificate)
    result = verify(cert_obj, signature_value.text, signed_data, algorithm="sha1")
    if not result:
        raise ValueError("Signature verification failed.")
    return True

