def retrieve_and_parse_diaspora_webfinger(handle):
    import requests
    from xml.etree import ElementTree

    url = f"https://{handle}.diaspora.example.com/users/webfinger"
    response = requests.get(url)
    if response.status_code == 200:
        xml_data = response.content
        root = ElementTree.fromstring(xml_data)
        for child in root:
            if child.tag == "link":
                if child.attrib["rel"] == "lrdd":
                    return {
                        "lrdd": {
                            "subject": child.attrib["subject"],
                            "aliases": [],
                        }
                    }
                elif child.attrib["rel"] == "self":
                    return {
                        "self": {
                            "subject": child.attrib["subject"],
                            "aliases": [],
                        }
                    }
                elif child.attrib["rel"] == "magic-public-key":
                    return {
                        "magic-public-key": {
                            "subject": child.attrib["subject"],
                            "aliases": [],
                        }
                    }
        return {}
    else:
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        with requests.Session() as session:
            response = session.request(method, url, data=data, timeout=timeout, *args, **kwargs)
            if response.status_code == 200:
                return response.status_code, None
            else:
                return None, handle_http_error(response)
    except Exception as e:
        return None, e

def handle_http_error(response):
    try:
        error = HTTPError.from_response(response)
    except Exception as e:
        return e
    else:
        return error

