def dict_insert(dic, val, key, *keys):
    # check if dic is a dictionary
    if not isinstance(dic, dict):
        raise TypeError("First argument must be a dictionary")

    # check if key is a string
    if not isinstance(key, str):
        raise TypeError("Second argument must be a string")

    # check if keys is a tuple of strings
    if not isinstance(keys, tuple) or not all(isinstance(k, str) for k in keys):
        raise TypeError("Third argument must be a tuple of strings")

    # initialize current dictionary to dic
    current_dict = dic

    # for each key in keys, create a new dictionary if it doesn't exist
    for k in keys:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]

    # insert the value into the current dictionary
    current_dict[key] = val

