def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content cannot be None")

    try:
        data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Error loading YAML data: {}".format(e))

    required_fields = ['version', 'resource', 'profile', 'version']

    for field in required_fields:
        if field not in data:
            raise IRValidatorException("Required field '{}' is missing in spec file".format(field))

    for key, value in data.items():
        if key not in required_fields:
            raise IRValidatorException("Unexpected field '{}' in spec file".format(key))

    return data

