    command = ['ansible-playbook', playbook_path]
    if verbose:
        command.append('-' + 'v' * verbose)
    if extra_vars:
        for var_name, var_value in extra_vars.items():
            command.append('-e')
            command.append(f"{var_name}={var_value}")
    if ansible_args:
        for arg_name, arg_value in ansible_args.items():
            command.append(f"--{arg_name}")
            command.append(arg_value)
    run_command(command, cwd=ir_workspace.root_path)
