def get_plugin_spec_flatten_dict(plugin_dir):
    # Load the plugin spec from the given directory
    spec = load_spec(plugin_dir)

    # Create a flatten dictionary to store the plugin's properties
    flatten_dict = {}

    # Loop through each property in the spec
    for property_name, property_value in spec.items():
        # If the property is a list, loop through each item in the list
        if isinstance(property_value, list):
            for item in property_value:
                # If the item is a dictionary, loop through each key-value pair
                if isinstance(item, dict):
                    for key, value in item.items():
                        # Add the key-value pair to the flatten dictionary
                        flatten_dict[key] = value
                # Otherwise, add the item to the flatten dictionary
                else:
                    flatten_dict[property_name] = item
        # If the property is a dictionary, loop through each key-value pair
        elif isinstance(property_value, dict):
            for key, value in property_value.items():
                # Add the key-value pair to the flatten dictionary
                flatten_dict[key] = value
        # Otherwise, add the property to the flatten dictionary
        else:
            flatten_dict[property_name] = property_value

    return flatten_dict
